import {analyze} from './parser.js';
import {defaults,validate,withToken} from './auth.js';
import {plan,enrich} from './graph.js';
import {translations} from './i18n.js';
const $=id=>document.getElementById(id),KEY='m365url.public-settings.v1';let lang='ja',settings={...defaults},result=null,tab='basic',busy=false;
const t=k=>translations[lang][k]||k;
const message=(key,target='status')=>$(target).textContent=t(key);
const node=(tag,text,className)=>{const n=document.createElement(tag);n.textContent=text;if(className)n.className=className;return n;};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved)settings=validate(saved);}catch{}
function setBusy(value){busy=value;for(const id of ['graph','analyze','clear','paste','settings'])$(id).disabled=value; $('graph').disabled=value||!result||!plan(result);for(const el of $('configForm').elements)el.disabled=value;$('url').disabled=value;}
function translate(){document.documentElement.lang=lang==='zh'?'zh-Hans':lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));fields();help();render();}
function fields(){const wrap=$('configFields');wrap.replaceChildren();for(const key of ['clientId','mode','tenantId','redirectUri','platform']){const row=node('div','','field'),label=node('label',t(key));label.htmlFor=key;row.append(label);let input;if(key==='mode'||key==='platform'){input=document.createElement('select');const opts=key==='mode'?[['multi',t('multi')],['single',t('single')]]:[['SPA','SPA'],['Web','Web']];for(const [v,s]of opts){const op=node('option',s);op.value=v;input.append(op);}}else{input=document.createElement('input');input.autocomplete='off';input.spellcheck=false;}input.id=key;input.value=settings[key];row.append(input);const reset=node('button','↺');reset.type='button';reset.title=t('reset');reset.setAttribute('aria-label',t('reset')+': '+t(key));reset.onclick=()=>{input.value=defaults[key];authority();};row.append(reset);input.oninput=authority;wrap.append(row);}authority();}
function authority(){const mode=$('mode').value,tenant=$('tenantId').value;$('authority').textContent='Authority: https://login.microsoftonline.com/'+(mode==='single'?tenant:'organizations');}
function formSettings(){return Object.fromEntries(['clientId','mode','tenantId','redirectUri','platform'].map(k=>[k,$(k).value.trim()]));}
function apply(persist=false){if(busy)return;try{settings=validate(formSettings());if(persist){const publicSettings={};for(const k of Object.keys(defaults))publicSettings[k]=settings[k];localStorage.setItem(KEY,JSON.stringify(publicSettings));}message(persist?'saved':'applied','configStatus');}catch(e){message(translations[lang][e.message]?e.message:'settingsError','configStatus');}}
function help(){const box=$('helpContent');box.replaceChildren();for(const k of ['guideTitle','guideText','permissions','graphNotice','authHelp','limits','authPrivacy','paNote'])box.append(node(k==='guideTitle'?'h3':'p',t(k)));const a=node('a','Microsoft Learn · Microsoft Graph');a.href='https://learn.microsoft.com/graph/permissions-reference';a.target='_blank';a.rel='noopener noreferrer';box.append(a);}
function paFields(){if(!result)return[];const keys=['Graph Team ID','Group ID','Channel ID','Chat ID','Message ID','Tenant ID','Site URL','Library Name','Server Relative Path','Folder Path','Drive ID','DriveItem ID','ListItem ID','List ID','Site ID'];return keys.flatMap(key=>{const matches=result.fields.filter(f=>f.key===key);return matches.length?[matches.find(f=>f.source==='graph')||matches[0]]:[];});}
function render(){if(!result)return;$('results').hidden=false;$('tabs').replaceChildren();for(const key of ['basic','teams','files','paths','automate','graphTab','json']){const b=node('button',t(key));b.setAttribute('role','tab');b.setAttribute('aria-selected',String(tab===key));b.id='tab-'+key;b.setAttribute('aria-controls','output');b.tabIndex=tab===key?0:-1;b.onclick=()=>{tab=key;render();};b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const all=[...$('tabs').children],i=all.indexOf(b),j=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;all[j].click();$('tabs').children[j].focus();}};$('tabs').append(b);}$('output').setAttribute('aria-labelledby','tab-'+tab);const out=$('output');out.replaceChildren();if(tab==='json'){out.append(node('pre',JSON.stringify(result,null,2)));return;}if(tab==='automate')out.append(node('p',t('paNote'),'empty'));if(tab==='graphTab')out.append(node('p',t('graphNotice'),'empty'));const values=tab==='automate'?paFields():result.fields.filter(f=>tab==='graphTab'?f.source==='graph':f.section===tab);if(!values.length)out.append(node('p',t('empty'),'empty'));for(const f of values){const row=node('div','','row'),key=node('div',f.key,'key'),val=node('div',f.value,'value'),meta=node('span',t(f.source==='graph'?'graphSource':'urlSource'),'meta'+(f.source==='graph'?' confirmed':'')),b=node('button',t('copy'));val.append(meta);b.setAttribute('aria-label',t('copy')+': '+f.key);b.onclick=()=>copy(f.value);row.append(key,val,b);out.append(row);}}
async function copy(text){try{await navigator.clipboard.writeText(text);message('copied');}catch{message('clipboard');}}
$('analyze').onclick=()=>{try{result=analyze($('url').value);tab='basic';render();setBusy(false);message('ready');}catch(e){result=null;$('results').hidden=true;$('graph').disabled=true;message(e.message);}};
$('url').oninput=()=>{result=null;$('graph').disabled=true;$('results').hidden=true;$('status').textContent='';};
$('clear').onclick=()=>{$('url').value='';result=null;$('results').hidden=true;$('graph').disabled=true;$('status').textContent='';$('url').focus();};
$('paste').onclick=async()=>{try{$('url').value=await navigator.clipboard.readText();$('analyze').click();}catch{message('clipboard');}};
$('copyAll').onclick=()=>result&&copy(result.fields.map(f=>`${f.key}: ${f.value} [${t(f.source==='graph'?'graphSource':'urlSource')}]`).join('\n'));
$('copyJson').onclick=()=>result&&copy(JSON.stringify(result,null,2));
$('settings').onclick=()=>{fields();$('config').showModal();};$('help').onclick=()=>$('helpDialog').showModal();$('appGuide').onclick=()=>$('helpDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('configForm').onsubmit=e=>{e.preventDefault();apply();};$('save').onclick=()=>apply(true);$('forget').onclick=()=>{try{localStorage.removeItem(KEY);message('forgot','configStatus');}catch{message('settingsError','configStatus');}};$('reset').onclick=()=>{if(!busy){settings={...defaults};try{localStorage.removeItem(KEY);}catch{}fields();message('applied','configStatus');}};
$('language').onchange=()=>{lang=$('language').value;translate();};
$('graph').onclick=async()=>{if(busy||!result)return;const task=plan(result);if(!task){message('unsupported');return;}setBusy(true); // Work on a fresh result to avoid mixing successive confirmations.
 const fresh=analyze(result.input);try{await withToken(settings,task.scopes,k=>message(k),token=>enrich(fresh,token,task));result=fresh;message('done');}catch(e){result=fresh;message(translations[lang][e.message]?e.message:'failed');}finally{render();setBusy(false);}};
const callbackContext=window.parent!==window||(/(?:^|[&#])(code|error|state)=/.test(location.hash)&&!!window.opener);
if(!callbackContext)translate();
// The endpoint returns only the shared total; no input URL is transmitted.
if(!callbackContext)try{let id=sessionStorage.getItem('m365url.visit');if(!id){id=crypto.randomUUID();sessionStorage.setItem('m365url.visit',id);}fetch('/api/visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),referrerPolicy:'no-referrer'}).then(r=>r.ok?r.json():null).then(v=>{if(Number.isSafeInteger(v?.count)&&v.count>=0)$('counter').textContent=String(v.count);}).catch(()=>{});}catch{}
